#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int n;
    int w3 = 0, w5 = 0, obu = 0;
    while (plik >> n) {
        if (n % 3 == 0) w3++;
        if (n % 5 == 0) w5++;
        if (n % 3 == 0 && n % 5 == 0) obu++;
    }
    cout << "Wielokrotnosci 3: " << w3 << endl;
    cout << "Wielokrotnosci 5: " << w5 << endl;
    cout << "Wielokrotnosci obu (3 i 5): " << obu << endl;
    return 0;
}
```

